import { useState } from "react";
import { postAdd } from "../../api/ManagerApi";
import ResultModal from "../common/ResultModal";
import useCustomMove from "../../hooks/useCustomMove";

const initState = {
 title: '', writer: '', dueDate: '' }

const AddComponent = () => {

  const [manager, setManager] = useState({...initState})
  //결과데이터가 있는 경우에는 ResultModal을 보여준다.
  const [result, setResult] = useState(null) //결과 상태
  const {moveToList} = useCustomMove()
  const handleChangeManager = (e) => {
    manager[e.target.name] = e.target.value
    setManager({...manager})
  }

const handleClickAdd = () => { postAdd(manager)
                               .then(result => {
                               setResult(result.userId) //결과 데이터 변경
                               setManager({...initState})
                               }).catch(e => { console.error(e) })
 }

return (
  <div className="border-2 border-sky-200 mt-10 m-2 p-4">
    {result ? (
      <ResultModal
        title={'Add Result'}
        content={`New ${result} Added`}
        callbackFn={closeModal}
      />
    ) : (
      <></>
    )}

    <div className="border-2 border-sky-200 mt-10 m-2 p-4">
      <div className="flex justify-center">
        <div className="relative mb-4 flex w-full flex-wrap items-stretch">
          <div className="w-1/5 p-6 text-right font-bold">NAME</div>
          <input
            className="w-4/5 p-6 rounded-r border border-solid border-neutral-500 shadow-md"
            name="mName"
            type={'text'}
            value={manager.mName}
            onChange={handleChangeManager}
          ></input>
        </div>
      </div>
      <div className="flex justify-center">
        <div className="relative mb-4 flex w-full flex-wrap items-stretch">
          <div className="w-1/5 p-6 text-right font-bold">ID</div>
          <input
            className="w-4/5 p-6 rounded-r border border-solid border-neutral-500 shadow-md"
            name="mID"
            type={'text'}
            value={manager.mID}
            onChange={handleChangeManager}
          ></input>
        </div>
        <div className="flex justify-end">
          <div className="relative mb-4 flex p-4 flex-wrap items-stretch">
            <button
              type="button"
              onClick={handleClickAdd}
              className="rounded p-4 w-36 bg-blue-500 text-xl text-white"
            >
              ADD
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
);
};
export default AddComponent;
